mapper.select:
SELECT rpia.id AS id, rpia.category_id AS categoryId, rpia.product_detail_id AS productDetailId, rpia.sku_no AS skuNo, rpia.attachment_id AS attachmentId, rpia.create_time AS createTime, rpia.create_user_name AS createUserName FROM ref_product_img_attachment rpia LEFT JOIN product_detail pd ON pd.id = rpia.product_detail_id AND pd.is_deleted = FALSE LEFT JOIN attachment att ON att.id = rpia.attachment_id AND att.is_deleted = FALSE WHERE ${params.sqlMap.default} AND rpia.is_deleted = FALSE
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
rpia.create_time desc

SELECT approve_status AS tabFlag, count(*) AS count FROM ref_product_img_attachment WHERE is_deleted=FALSE
${params.permissionSql}
GROUP BY approve_status
